using System.Text.Json.Serialization;

namespace Elevant.Contracts.Integration;

/// <summary>
/// «Disparar vuelo demo» (ADR-0041). <paramref name="DestinationIata"/> null is the origin: the aircraft returns where
/// it came from. <paramref name="StandChoice"/> is <c>None</c>, <c>Specific</c> (with <paramref name="StandId"/>, which
/// must be eligible) or <c>Random</c> (without a stand: the server draws one of the eligible stands with the
/// Idempotency-Key as the seed, so a retry gets the same one); the flight numbers and the registration are generated by
/// the server, never typed.
/// </summary>
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed record CreateDemoFlightRequest(Guid StationId, Guid AirlineId, string OriginIata, string? DestinationIata,
    Guid AircraftTypeId, string StandChoice, Guid? StandId, int MinutesToOnBlock, int GroundMinutes);

/// <summary>
/// «Cancelar vuelo» (<c>Cancel</c>, before touchdown) or «Terminar demo» (<c>Finish</c>, after it). The intent is
/// checked against the phase of the flight; there is no expected version because the progress worker's stamps make
/// row versions stale by design.
/// </summary>
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed record CancelDemoFlightRequest(string Intent);

/// <summary>
/// A demo flight as the superadministrator follows it. <paramref name="State"/> is Active, Cancelled or Finished and
/// <paramref name="Phase"/> Approach, TaxiIn, Parked, TaxiOut, Departed or Gone, at the server time of the answer.
/// Every instant comes from the server's demo clock: no screen derives one. <paramref name="SuggestedStandCode"/> is
/// the stand the trigger proposed; once OCC imported the flight (<paramref name="Imported"/>) the turnaround, its
/// operation and the stand OCC assigned follow.
/// </summary>
public sealed record DemoFlightResponse(Guid Id, Guid StationId, string StationCode, Guid AirlineId, string AirlineName,
    string ArrivalFlightNumber, string DepartureFlightNumber, string AircraftRegistration, string AircraftModel,
    string OriginIata, string DestinationIata, string? SuggestedStandCode, string State, string Phase,
    DateTimeOffset AppearAt, DateTimeOffset TouchdownAt, DateTimeOffset OnBlockAt, DateTimeOffset ScheduledOffBlockAt,
    DateTimeOffset? OffBlockAt, DateTimeOffset? TakeoffAt, DateTimeOffset? VanishAt, bool Imported, Guid? TurnaroundId,
    string? OperationCode, string? StandCode, string? OperationStatus);

/// <summary>
/// The demo flights of the last 24 hours at a station, newest first (at most 50). With the feature off in this
/// environment <paramref name="Enabled"/> is false and the list is empty.
/// </summary>
public sealed record DemoFlightListResponse(bool Enabled, DateTimeOffset ServerTime, Guid? StationId,
    IReadOnlyList<DemoFlightResponse> Flights);

/// <summary>
/// What the form «Disparar vuelo demo» offers at a station: the airlines with exactly one applicable contract on
/// <paramref name="OperationDate"/> (the station's local day), the airports, the active aircraft types, the stands
/// evaluated for the visit the query asked about, the limits, the warnings that never block and the station against the
/// Punta Cana catalogue (<paramref name="Layout"/>, null without a station). With the feature off
/// <paramref name="Enabled"/> is false, every list is empty and there is no layout.
/// </summary>
public sealed record DemoFlightOptionsResponse(bool Enabled, DateTimeOffset ServerTime,
    IReadOnlyList<DemoStationOptionResponse> Stations, Guid? StationId, DateOnly? OperationDate,
    IReadOnlyList<DemoAirlineOptionResponse> Airlines, IReadOnlyList<DemoAirportOptionResponse> Airports,
    IReadOnlyList<DemoAircraftTypeOptionResponse> AircraftTypes, IReadOnlyList<DemoStandOptionResponse> Stands,
    DemoFlightLimitsResponse Limits, IReadOnlyList<DemoFlightWarningResponse> Warnings, DemoStationLayoutResponse? Layout);

public sealed record DemoStationOptionResponse(Guid Id, string Code, string Name);

public sealed record DemoAirlineOptionResponse(Guid Id, string Name, string? IataCode, string IcaoCode);

public sealed record DemoAirportOptionResponse(string IataCode, string IcaoCode, string Name, string City,
    string CountryCode);

/// <summary><paramref name="SizeCategory"/> is Narrowbody, Widebody or null when unknown.</summary>
public sealed record DemoAircraftTypeOptionResponse(Guid Id, string IcaoCode, string Manufacturer, string Model,
    string? SizeCategory);

/// <summary>
/// An active stand of an active terminal, for the visit the options were read for (ADR-0041, contracts 1.1).
/// <paramref name="Located"/>: the map knows where it is (its code is in the Punta Cana catalogue, or OCC placed it).
/// <paramref name="Free"/>: nothing occupies it during the visit (combined stands and the aircraft size included) and no
/// other active demo flight suggests it. <paramref name="CoveredBy"/>: the agents whose position coverage includes it at
/// the on-block instant, by name, of whom <paramref name="EligibleAgents"/> pass OCC's assignment rule.
/// <paramref name="Eligible"/>: located, free and with at least one such agent; only an eligible stand is drawn by
/// <c>Random</c> or accepted by <c>Specific</c>. <paramref name="Reasons"/>: why a located and free stand is not
/// eligible (<c>stand_not_covered</c>, or the codes of the assignment rule); empty otherwise.
/// </summary>
public sealed record DemoStandOptionResponse(Guid StandId, string Code, string TerminalCode, bool Located, bool Free,
    IReadOnlyList<string> CoveredBy, int EligibleAgents, bool Eligible, IReadOnlyList<string> Reasons);

/// <summary>The ranges of the form and how many demo flights are active at the station out of <paramref name="MaxActive"/>.</summary>
public sealed record DemoFlightLimitsResponse(int MinMinutesToOnBlock, int MaxMinutesToOnBlock, int DefaultMinutesToOnBlock,
    int MinGroundMinutes, int MaxGroundMinutes, int DefaultGroundMinutes, int MaxActive, int Active);

/// <summary>Something the superadministrator should know before triggering; it never blocks the command.</summary>
public sealed record DemoFlightWarningResponse(string Code, IReadOnlyList<string> Reasons);

/// <summary>
/// «Cargar posiciones de Punta Cana» (ADR-0041, contracts 1.2) at a station: the catalogue's terminals and stands it
/// lacks are created, active and without coordinates, and nothing it has is changed. Only Punta Cana has a catalogue.
/// </summary>
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed record PrepareDemoStationRequest(Guid StationId);

/// <summary>
/// A station against the Punta Cana catalogue (ADR-0041, contracts 1.2), as the card «Posiciones de Punta Cana» shows it:
/// the answer of «Cargar posiciones» (the station as it is afterwards, so the first run and a replay answer the same) and
/// the <c>layout</c> of the demo flight options. <paramref name="Supported"/> is false for a station without a catalogue,
/// whose counts are zero and whose lists are empty. <paramref name="Terminals"/>: the catalogue's terminals the station
/// has active, out of <paramref name="CatalogTerminals"/>. <paramref name="Stands"/>: the catalogue's stands it has as an
/// active stand of an active terminal, out of <paramref name="CatalogStands"/>; the others are
/// <paramref name="MissingStands"/>, in the catalogue's spelling and order. <paramref name="ActiveStands"/>: every active
/// stand of an active terminal, of which <paramref name="LocatedStands"/> are located on the map and
/// <paramref name="UnmatchedStands"/>, with the codes they have, are not the catalogue's. <paramref name="Complete"/>: the
/// catalogue's terminals are active and no stand is missing; stands outside the catalogue never count against it.
/// </summary>
public sealed record DemoStationLayoutResponse(Guid StationId, string StationCode, bool Supported, int CatalogTerminals,
    int Terminals, int CatalogStands, int Stands, int ActiveStands, int LocatedStands,
    IReadOnlyList<string> MissingStands, IReadOnlyList<string> UnmatchedStands, bool Complete);
